import { createWebProjectionBatch } from './web.js';
import { createWebProjectionScope } from './scope.js';
/** A renderer supplies placement policy; the Engine owns the complete image handoff. */
export const createWebProjectionSurface = async (transport, options) => {
    const scopes = new WeakMap();
    const moved = new Map();
    const restorePlacement = () => {
        for (const [element, saved] of [...moved].reverse()) {
            if (element.parentNode === saved.layer && saved.parent.isConnected)
                saved.parent.insertBefore(element, saved.next?.parentNode === saved.parent ? saved.next : null);
        }
        moved.clear();
    };
    const projection = await createWebProjectionBatch(transport, {
        ...options,
        wake: () => {
            if (!projection.token && !projection.restoring)
                restorePlacement();
            options.wake();
        },
    });
    let latest = [];
    const { consider, begin, updated, invalidate, destroy } = projection;
    return Object.assign(projection, {
        consider(revision, sources) {
            latest = sources;
            consider(revision, sources.flatMap((source) => {
                const target = options.target(source);
                if (!target?.isConnected || target.ownerDocument !== source.element.ownerDocument)
                    return [];
                let scope = scopes.get(target);
                if (!scope) {
                    scope = createWebProjectionScope(target, options.namespace);
                    scopes.set(target, scope);
                }
                return [{ ...source, scope }];
            }));
        },
        begin(layer) {
            if (layer && !layer.isConnected)
                return;
            if (layer && !projection.token) {
                for (const source of latest) {
                    if (!projection.preparedOwners.includes(source.element))
                        continue;
                    const target = options.target(source);
                    if (!target?.isConnected ||
                        !target.parentNode ||
                        target.ownerDocument !== layer.ownerDocument ||
                        layer.contains(target) ||
                        target.contains(layer) ||
                        !options.canRelocate?.(target))
                        continue;
                    if (!moved.has(target))
                        moved.set(target, { parent: target.parentNode, next: target.nextSibling, layer });
                    layer.append(target);
                }
            }
            begin();
            if (!projection.token)
                restorePlacement();
        },
        updated(token, ids, revision) {
            updated(token, ids, revision);
            if (!projection.restoring && !projection.token)
                restorePlacement();
        },
        invalidate(nativeHidden) {
            invalidate(nativeHidden);
            restorePlacement();
        },
        async destroy() {
            try {
                await destroy();
            }
            finally {
                restorePlacement();
            }
        },
    });
};
